/** Maps a public image path to its pre-built WebP variant (generated by scripts/build-images.mjs). */
export const WIDTHS = [256, 384, 640, 828, 1080, 1280, 1920];

export function imgUrl(src: string, width = 1280): string {
  if (!src || /^(https?:|data:)/.test(src) || !/\.(jpe?g|png|webp)$/i.test(src.split("?")[0])) return src;
  const clean = src.split("?")[0];
  const w = WIDTHS.find((x) => x >= width) ?? WIDTHS[WIDTHS.length - 1];
  return `/_img${clean.slice(0, clean.lastIndexOf("."))}-${w}.webp`;
}

export default function loader({ src, width }: { src: string; width: number; quality?: number }) {
  return imgUrl(src, width);
}
